mapper.select:
SELECT * FROM ( SELECT a.*,FORMAT(wdate, 'yyyy-MM-dd') AS formatted_date, (SELECT COUNT(*) FROM KCC_EGIS.egis.TBL_NEWS_PHOTO b WHERE b.info_num = a.num) AS photo_count FROM KCC_EGIS.egis.TBL_NEWS a WHERE 1=1 and flag = 'N'
and a.part = #{part}
and (a.subject like CONCAT('%', #{searchKeyword}, '%') or a.keyword_tag like CONCAT('%', #{searchKeyword}, '%'))
and CONVERT(char(10),a.wdate,23) BETWEEN #{sdate} AND #{edate}
) A
ORDER BY num desc
ORDER BY ${otype} DESC

select count(*) from ( SELECT a.*, (SELECT COUNT(*) FROM KCC_EGIS.egis.TBL_NEWS_PHOTO b WHERE b.info_num = a.num) AS photo_count FROM KCC_EGIS.egis.TBL_NEWS a WHERE 1=1 and flag = 'N'
and a.part = #{part}
and (a.subject like CONCAT('%', #{searchKeyword}, '%') or a.keyword_tag like CONCAT('%', #{searchKeyword}, '%'))
and CONVERT(char(10),a.wdate,23) BETWEEN #{sdate} AND #{edate}
) A
